    def _ordinal(s):
        y = int(s[0:4])
        m = int(s[5:7])
        d = int(s[8:10])
        days = (y - 1) * 365 + (y - 1) // 4 - (y - 1) // 100 + (y - 1) // 400
        months = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        leap = (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)
        for i in range(m - 1):
            days += months[i]
            if i == 1 and leap:
                days += 1
        days += d
        return days
    diff = _ordinal(event_date) - _ordinal(reference_date)
    return diff + 1 if diff >= 0 else diff
